import json
import os
from pathlib import Path
from boltons import mathutils

assert Path(mathutils.__file__).resolve().is_relative_to(Path(os.environ['PROBE_COPY']).resolve())
Bits = mathutils.Bits
results = []


def check(name, function):
    try:
        detail = function()
        results.append({'id': name, 'status': 'pass', 'detail': detail})
    except Exception as exc:
        results.append({'id': name, 'status': 'fail', 'error': type(exc).__name__, 'message': str(exc)})


def eq(actual, expected):
    assert actual == expected, (repr(actual), repr(expected))


def empty(value):
    eq((len(value), value.as_int(), value.as_bin(), value.as_hex(), value.as_bytes(), value.as_list()),
       (0, 0, '', '', b'', []))
    eq(repr(value), "Bits('')")


def constructors():
    for value in (Bits(''), Bits(b''), Bits([]), Bits(0, 0), Bits.from_bin(''),
                  Bits.from_bin(b''), Bits.from_list([]), Bits.from_int(0, 0)):
        empty(value)


def hex_byte_roundtrip():
    for value in (Bits.from_hex(''), Bits.from_hex(b''), Bits.from_bytes(b'')):
        empty(value)
    zero = Bits(0, 0)
    for value in (Bits.from_hex(zero.as_hex()), Bits.from_bytes(zero.as_bytes()),
                  Bits.from_bin(zero.as_bin()), Bits.from_list(zero.as_list())):
        empty(value)


def empty_slices_and_indices():
    value = Bits('10101')
    before = (value.val, value.len)
    for item in (value[1:1], value[50:], value[:0], Bits('')[:], value[4:1]):
        empty(item)
        for index in (0, -1):
            try:
                item[index]
            except IndexError:
                pass
            else:
                raise AssertionError('empty bit indexing accepted')
    eq((value.val, value.len), before)
    eq(value[::-1].as_bin(), '10101')


def nonempty_serialization():
    for value, width, binary, hexadecimal, raw in ((0, 1, '0', '00', b'\0'),
         (0, 8, '00000000', '00', b'\0'), (5, 3, '101', '05', b'\x05'),
         (0x109, 9, '100001001', '0109', b'\x01\x09')):
        item = Bits(value, width)
        eq((len(item), item.as_bin(), item.as_hex(), item.as_bytes()), (width, binary, hexadecimal, raw))
        eq(item.as_list(), [char == '1' for char in binary])
        eq(Bits.from_bytes(raw).as_bytes(), raw)
        eq(Bits.from_hex(hexadecimal).as_hex(), hexadecimal)
    eq(len(Bits(0)), 1)
    assert Bits(0) != Bits(0, 0)


def errors():
    cases = [(lambda: Bits(-1), ValueError), (lambda: Bits(1, 0), ValueError),
             (lambda: Bits(4, 2), ValueError), (lambda: Bits('102'), ValueError),
             (lambda: Bits.from_hex('gg'), ValueError), (lambda: Bits('0xg'), ValueError),
             (lambda: Bits('0x '), ValueError), (lambda: Bits(None), TypeError),
             (lambda: Bits(b'\xff'), UnicodeDecodeError),
             (lambda: Bits.from_hex(b'\xff'), UnicodeDecodeError)]
    for function, expected in cases:
        try:
            function()
        except expected:
            pass
        else:
            raise AssertionError(f'{expected.__name__} not raised')


def bit_operations():
    empty(Bits('') | Bits(''))
    empty(Bits('') & Bits(''))
    empty(Bits('1') >> 1)
    eq((Bits('') << 3).as_bin(), '000')
    eq((Bits('101') | Bits('010')).as_bin(), '111')


def prefix_observations():
    observed = {}
    for label, function in [('direct_str', lambda: Bits('0x')),
                            ('direct_bytes', lambda: Bits(b'0x')),
                            ('hex_str', lambda: Bits.from_hex('0x')),
                            ('hex_bytes', lambda: Bits.from_hex(b'0x')),
                            ('explicit_width_three', lambda: Bits('0x', 3))]:
        try:
            value = function()
            observed[label] = {'accepted': True, 'width': len(value), 'value': value.as_int(), 'binary': value.as_bin()}
        except Exception as exc:
            observed[label] = {'accepted': False, 'error': type(exc).__name__}
    return observed


check('empty_constructors_all_serializers', constructors)
check('empty_hex_bytes_roundtrip', hex_byte_roundtrip)
check('empty_slices_indices_ownership', empty_slices_and_indices)
check('nonempty_width_padding_zero_distinction', nonempty_serialization)
check('invalid_input_error_contract', errors)
check('bit_operations_zero_width', bit_operations)
check('prefix_only_token_observation', prefix_observations)
print(json.dumps({'module': mathutils.__file__, 'results': results}, ensure_ascii=True))
